BACKLOG = 3
TIMEOUT = 5
events = [(0, 'SYN', 'x1'), (1, 'SYN', 'x2'), (2, 'SYN', 'x3'), (8, 'SYN', 'amy'), (9, 'ACK', 'amy')]
backlog = {}
done = []

def fresh(backlog, now):
    # now까지 TIMEOUT보다 짧게 기다린 항목만 남긴 새 사전을 돌려줘요.
    return {w: s for w, s in backlog.items() if now - s < TIMEOUT}

for t, kind, who in events:
    # 이 주석 아래에서 오래 기다린 반개방 항목을 지우세요.
    if kind == 'SYN':
        if len(backlog) >= BACKLOG:
            print(t, who, 'refused')
            continue
        backlog[who] = t
    elif kind == 'ACK' and who in backlog:
        del backlog[who]
        done.append(who)
print('half-open', sorted(backlog), 'established', done)

