routers = ['r1', 'r2', 'r3']
known = ['192.0.2.9']
dst = '192.0.2.9'

def ping(dst, ttl):
    if dst not in known:
        return routers[0] + ': destination unreachable'
    for r in routers:
        ttl -= 1
        if ttl == 0:
            return r + ': time exceeded'
    return dst + ': echo reply'

# TTL을 1부터 하나씩 늘리며 누가 대답하는지 봐요.
for ttl in range(1, len(routers) + 2):
    print(ttl, ping(dst, ttl))

