records = {'com': 'com-ns', 'shop.com': 'shop-ns', 'www.shop.com': '198.51.100.20', 'api.shop.com': '198.51.100.21'}
cache = {}
queries = ['www.shop.com', 'api.shop.com', 'www.shop.com']

def resolve(name):
    if name in cache:
        return cache[name], 0
    parts = name.split('.')
    asked = 0
    # 뒤에서부터 com, shop.com, www.shop.com 순서로 물어요.
    for i in range(len(parts) - 1, -1, -1):
        answer = records['.'.join(parts[i:])]
        asked += 1
    # 이 주석 아래에 받은 답을 캐시에 적으세요.
    return answer, asked

for q in queries:
    ip, asked = resolve(q)
    print(q, ip, 'asked', asked)

